async def criar_tabela_cartilha_i18n():
    """Startup: tabela de traduções + coluna idioma_manual no usuário + carga
    inicial (só onde ainda não existe tradução). Nunca sobrescreve."""
    for sql in CARTILHA_I18N_SQL.split(";"):
        if sql.strip():
            await ajard_query(sql, fetch="none")
    for titulo_pt, idioma, titulo, subtitulo, conteudo in CARTILHA_SEED_I18N:
        await ajard_query(
            "INSERT INTO public.cartilha_traducoes (bloco_id, idioma, titulo, subtitulo, conteudo) "
            "SELECT b.id, %s, %s, %s, %s FROM public.cartilha_blocos b "
            "WHERE b.titulo=%s AND NOT EXISTS (SELECT 1 FROM public.cartilha_traducoes t WHERE t.bloco_id=b.id AND t.idioma=%s)",
            (idioma, titulo, subtitulo, conteudo, titulo_pt, idioma), fetch="none")
